#include <WiFi.h>
#include <WebServer.h>

const char* ssid     = "TP-LINK_LWL";
const char* password = "luoshi8722";

const uint8_t soilSensorPin = 34;
const uint8_t pumpPin       = 2;
const uint8_t ledGreen      = 13;
const uint8_t ledYellow     = 14;
const uint8_t ledRed        = 27;
const uint8_t buzzerPin     = 26;

int dryValue       = 3200;
int wetValue       = 1200;
int warnThreshold  = 2600;
int runThreshold   = 2800;

// 每次浇水5秒
unsigned long waterMaxTime= 5000;

unsigned long waterStartTick = 0;

bool pumpRunning = false;

// 浇完一次以后，等待土壤变湿
bool waitingForMoisture = false;

WebServer server(80);


// ==================== 网页 ====================

void handleRoot() {
  int soilVal = analogRead(soilSensorPin);

  String html = "<html>";
  html += "<h2>ESP32自动浇花控制器</h2>";
  html += "<p>土壤湿度原始值：" + String(soilVal) + "</p>";
  html += "<p>水泵状态：" +
          String(pumpRunning ? "正在浇水" : "待机") +
          "</p>";
  html += "<a href=\"/pump_on\"><button style='font-size:24px'>手动开泵</button></a> ";
  html += "<a href=\"/pump_off\"><button style='font-size:24px'>手动关泵</button></a>";
  html += "</html>";

  server.send(200, "text/html", html);
}


// ==================== 水泵控制 ====================

void startPump() {
  digitalWrite(pumpPin, HIGH);
  pumpRunning = true;
  waterStartTick = millis();
}

void stopPump() {
  digitalWrite(pumpPin, LOW);
  pumpRunning = false;
}


// 网页手动开泵
void pumpON() {
  startPump();
  server.send(200, "text/plain", "水泵开启");
}


// 网页手动关泵
void pumpOFF() {
  stopPump();
  server.send(200, "text/plain", "水泵关闭");
}


// ==================== WiFi ====================

void setupWeb() {

  WiFi.begin(ssid, password);

  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
  }

  server.on("/", handleRoot);
  server.on("/pump_on", pumpON);
  server.on("/pump_off", pumpOFF);

  server.begin();
}


// ==================== LED ====================

void setLED(uint8_t green, uint8_t yellow, uint8_t red) {

  digitalWrite(ledGreen, green);
  digitalWrite(ledYellow, yellow);
  digitalWrite(ledRed, red);
}


// ==================== 初始化 ====================

void setup() {

  Serial.begin(115200);

  Serial.println("================================");
  Serial.println("自动浇花神器 V2 - 5秒版");
  Serial.println("浇水时间：5000ms");
  Serial.println("================================");
  pinMode(pumpPin, OUTPUT);
  pinMode(ledGreen, OUTPUT);
  pinMode(ledYellow, OUTPUT);
  pinMode(ledRed, OUTPUT);
  pinMode(buzzerPin, OUTPUT);

  digitalWrite(pumpPin, LOW);

  digitalWrite(ledGreen, LOW);
  digitalWrite(ledYellow, LOW);
  digitalWrite(ledRed, LOW);

  digitalWrite(buzzerPin, LOW);

  setupWeb();

  Serial.print("设备IP地址：");
  Serial.println(WiFi.localIP());
}


// ==================== 主程序 ====================

void loop() {

  server.handleClient();

  int soilVal = analogRead(soilSensorPin);

  Serial.print("湿度读数：");
  Serial.println(soilVal);


  // --------------------------------
  // 正在浇水
  // --------------------------------

  if (pumpRunning) {

    setLED(LOW, LOW, HIGH);

    // 浇水5秒后停止
    if (millis() - waterStartTick >= waterMaxTime) {

      stopPump();

      // 进入等待状态
      waitingForMoisture = true;

      Serial.println("浇水5秒完成，水泵停止");
    }
  }


  // --------------------------------
  // 没有浇水
  // --------------------------------

  else {

    // 土壤已经湿润
    if (soilVal < warnThreshold) {

      setLED(HIGH, LOW, LOW);

      // 允许下一次自动浇水
      waitingForMoisture = false;
    }


    // 土壤偏干
    else if (soilVal < runThreshold) {

      setLED(LOW, HIGH, LOW);
    }


    // 土壤很干
    else {

      setLED(LOW, LOW, HIGH);

      // 只有不在等待状态时，才能启动水泵
      if (!waitingForMoisture) {

        digitalWrite(buzzerPin, HIGH);
        delay(200);
        digitalWrite(buzzerPin, LOW);

        startPump();

        Serial.println("土壤干燥，开始浇水");
      }
    }
  }

  delay(1000);
}
